OUTPUTS = {'ontology/governed_effector_adapter.py': '"""P162-G5 Governed Effector Mediation.\n\nReference causal boundary. No ambient filesystem/network/subprocess/database primitive\nis imported here. A concrete effector must be explicitly injected and registered.\n"""\nfrom dataclasses import dataclass\nfrom threading import RLock\nfrom hashlib import sha256\nimport json\n\n@dataclass(frozen=True)\nclass EffectAttemptRecord:\n    attempt_id:str\n    lease_id:str\n    reservation_id:str\n    claim_hash:str\n    handle_id:str\n    broker_use_id:str\n    adapter_id:str\n    effector_id:str\n    operation_id:str\n    target_binding:object\n    status:str\n    started_at:str\n    idempotency_key:str\n    attempt_hash:str\n\n@dataclass(frozen=True)\nclass ExecutionReceipt:\n    execution_id:str\n    reservation_id:str\n    lease_id:str\n    adapter_id:str\n    adapter_version:str\n    capability_id:str\n    capability_version:str\n    operation:str\n    effective_target:object\n    effect_class:str\n    effect_status:str\n    uncertainty:bool\n    idempotency_reference:str\n    external_receipts:object\n    resource_usage:object\n    receipt_hash:str\n\nclass GovernedEffectorAdapter:\n    """Mediated entry point for an explicitly injected effector.\n\n    Replay exclusion is per adapter object in one process. It does not replace\n    the durable reservation/claim authority: restart, multiple adapter objects\n    and multiple hosts need their own verified shared authority before use.\n    """\n    def __init__(self, *, adapter_id, adapter_version, adapter_hash, effector_id,\n                 effector_callable, allowed_effect_classes):\n        if not callable(effector_callable): raise TypeError("effector_callable_required")\n        self.adapter_id=adapter_id; self.adapter_version=adapter_version\n        self.adapter_hash=adapter_hash; self.effector_id=effector_id\n        self._effector=effector_callable\n        self.allowed_effect_classes=frozenset(allowed_effect_classes)\n        self._lock=RLock(); self._attempted=set()\n        self._attempted_leases=set(); self._attempted_reservations=set()\n\n    def execute(self, *, claim, handle, brokered_use, registry_entry,\n                capability_id, capability_version, effect_class,\n                final_state, idempotency_key, now_iso):\n        # Binding chain G2 -> G3 -> G4 -> registered adapter/effector.\n        if claim is None or handle is None or brokered_use is None:\n            return {"status":"EXECUTION_BLOCKED_AT_FINAL_RECHECK","reason":"incomplete_mediation_chain","receipt":None}\n        checks=[\n          (claim.adapter_id==self.adapter_id,"claim_adapter_mismatch"),\n          (handle.lease_id==claim.lease_id,"handle_lease_mismatch"),\n          (handle.reservation_id==claim.reservation_id,"handle_reservation_mismatch"),\n          (brokered_use.lease_id==claim.lease_id,"credential_lease_mismatch"),\n          (brokered_use.reservation_id==claim.reservation_id,"credential_reservation_mismatch"),\n          (brokered_use.claim_hash==claim.claim_hash,"credential_claim_mismatch"),\n          (handle.claim_hash==claim.claim_hash,"handle_claim_mismatch"),\n          (handle.adapter_id==self.adapter_id,"handle_adapter_mismatch"),\n          (handle.effector_id==self.effector_id,"handle_effector_mismatch"),\n          (brokered_use.handle_id==handle.handle_id,"credential_handle_mismatch"),\n          (brokered_use.adapter_id==self.adapter_id,"credential_adapter_mismatch"),\n          (brokered_use.effector_id==self.effector_id,"credential_effector_mismatch"),\n          (brokered_use.allowed_operation==handle.operation_id,"credential_operation_mismatch"),\n          (brokered_use.target_binding==handle.target_binding,"credential_target_mismatch"),\n          (registry_entry.get("status")=="ACTIVE","adapter_not_active"),\n          (registry_entry.get("adapter_id")==self.adapter_id,"registry_adapter_mismatch"),\n          (registry_entry.get("adapter_hash")==self.adapter_hash,"adapter_identity_drift"),\n          (registry_entry.get("effector_id")==self.effector_id,"registry_effector_mismatch"),\n          (effect_class in self.allowed_effect_classes,"effect_class_not_allowed"),\n          (final_state.get("lease_current") is True,"lease_not_current"),\n          (final_state.get("reservation_current") is True,"reservation_not_current"),\n          (final_state.get("revoked") is not True,"last_second_revocation"),\n          (final_state.get("target_current") is True,"target_not_current"),\n          (final_state.get("critical_preconditions_satisfied") is True,"critical_precondition_failed"),\n          (final_state.get("security_state")=="VERIFIED","security_not_verified"),\n          (final_state.get("adapter_attestation")==self.adapter_hash,"adapter_attestation_mismatch"),\n        ]\n        for ok,reason in checks:\n            if not ok:return {"status":"EXECUTION_BLOCKED_AT_FINAL_RECHECK","reason":reason,"receipt":None}\n        if not idempotency_key:\n            return {"status":"EXECUTION_BLOCKED_AT_FINAL_RECHECK","reason":"idempotency_key_required","receipt":None}\n        # A caller-chosen correlation key cannot manufacture a second use of\n        # the same lease or reservation. Consume before dispatch; an exception\n        # or an unknown outcome never releases these identities for retry.\n        identities=(claim.lease_id,claim.reservation_id,claim.claim_hash,idempotency_key)\n        if any(type(value) is not str or not value.strip() for value in identities):\n            return {"status":"EXECUTION_BLOCKED_AT_FINAL_RECHECK","reason":"invalid_execution_identity","receipt":None}\n        attempt_key=(claim.lease_id,claim.reservation_id)\n        with self._lock:\n            if (claim.lease_id in self._attempted_leases or\n                    claim.reservation_id in self._attempted_reservations):\n                return {"status":"EXECUTION_BLOCKED_AT_FINAL_RECHECK","reason":"effect_attempt_replay","receipt":None}\n            self._attempted.add(attempt_key)\n            self._attempted_leases.add(claim.lease_id)\n            self._attempted_reservations.add(claim.reservation_id)\n        payload={"lease_id":claim.lease_id,"reservation_id":claim.reservation_id,"claim_hash":claim.claim_hash,\n                 "handle_id":handle.handle_id,"broker_use_id":brokered_use.broker_use_id,\n                 "adapter_id":self.adapter_id,"effector_id":self.effector_id,"operation_id":handle.operation_id,\n                 "target_binding":handle.target_binding,"started_at":now_iso,"idempotency_key":idempotency_key}\n        ah=sha256(json.dumps(payload,sort_keys=True,separators=(",",":"),default=str).encode()).hexdigest()\n        attempt=EffectAttemptRecord(attempt_id=ah,attempt_hash=ah,status="EXECUTION_STARTED",**payload)\n        try:\n            outcome=self._effector(operation=handle.operation_id,target=handle.target_binding,\n                                   credential_ref=brokered_use.credential_ref,\n                                   idempotency_key=idempotency_key)\n        except TimeoutError:\n            return {"status":"EFFECT_STATE_INDETERMINATE","reason":"timeout_after_possible_dispatch",\n                    "attempt":attempt,"receipt":None,"blind_retry_allowed":False}\n        except Exception as exc:\n            # Exception does not prove that a non-idempotent external effect did not occur.\n            return {"status":"EFFECT_STATE_INDETERMINATE","reason":"effector_exception",\n                    "attempt":attempt,"receipt":None,"blind_retry_allowed":False,\n                    "exception_type":type(exc).__name__}\n        if not isinstance(outcome,dict) or outcome.get("effect_status") not in {\n            "EFFECT_CONFIRMED","EFFECT_PARTIAL","EFFECT_FAILED_CONFIRMED","EFFECT_NOT_REACHED"}:\n            return {"status":"EFFECT_STATE_INDETERMINATE","reason":"unverifiable_effector_outcome",\n                    "attempt":attempt,"receipt":None,"blind_retry_allowed":False}\n        status=outcome["effect_status"]; uncertainty=False\n        rp={"execution_id":ah,"reservation_id":claim.reservation_id,"lease_id":claim.lease_id,\n            "adapter_id":self.adapter_id,"adapter_version":self.adapter_version,\n            "capability_id":capability_id,"capability_version":capability_version,\n            "operation":handle.operation_id,"effective_target":handle.target_binding,\n            "effect_class":effect_class,"effect_status":status,"uncertainty":uncertainty,\n            "idempotency_reference":idempotency_key,"external_receipts":outcome.get("external_receipts",[]),\n            "resource_usage":outcome.get("resource_usage",{})}\n        rh=sha256(json.dumps(rp,sort_keys=True,separators=(",",":"),default=str).encode()).hexdigest()\n        receipt=ExecutionReceipt(receipt_hash=rh,**rp)\n        return {"status":status,"reason":None,"attempt":attempt,"receipt":receipt,\n                "blind_retry_allowed": status in {"EFFECT_FAILED_CONFIRMED","EFFECT_NOT_REACHED"}}\n', 'tests/test_p162_g5_replay_hardening.py': '"""Bounded G5 regression tests; synthetic inputs and in-memory effects only."""\nfrom concurrent.futures import ThreadPoolExecutor\nfrom pathlib import Path\nfrom threading import Barrier, Lock\nfrom types import SimpleNamespace\nimport importlib.util\nimport sys\nimport unittest\n\nROOT = Path(__file__).resolve().parents[1]\nSPEC = importlib.util.spec_from_file_location(\n    "p162_g5_under_test", ROOT / "ontology/governed_effector_adapter.py")\nMODULE = importlib.util.module_from_spec(SPEC)\nsys.modules[SPEC.name] = MODULE\nSPEC.loader.exec_module(MODULE)\n\n\ndef inputs(lease="L1", reservation="R1", claim_hash="CH1", key="K1"):\n    target = {"path": "synthetic-target"}\n    claim = SimpleNamespace(lease_id=lease, reservation_id=reservation,\n                            claim_hash=claim_hash, adapter_id="A1")\n    handle = SimpleNamespace(lease_id=lease, reservation_id=reservation,\n                             claim_hash=claim_hash, adapter_id="A1",\n                             effector_id="E1", handle_id="H1",\n                             operation_id="WRITE", target_binding=target)\n    credential = SimpleNamespace(lease_id=lease, reservation_id=reservation,\n                                 claim_hash=claim_hash, adapter_id="A1",\n                                 effector_id="E1", handle_id="H1",\n                                 allowed_operation="WRITE", target_binding=target,\n                                 broker_use_id="B1", credential_ref="opaque-test-ref")\n    return dict(claim=claim, handle=handle, brokered_use=credential,\n                registry_entry=dict(status="ACTIVE", adapter_id="A1",\n                                    adapter_hash="AH1", effector_id="E1"),\n                capability_id="C1", capability_version="1", effect_class="TEST",\n                final_state=dict(lease_current=True, reservation_current=True,\n                                 revoked=False, target_current=True,\n                                 critical_preconditions_satisfied=True,\n                                 security_state="VERIFIED", adapter_attestation="AH1"),\n                idempotency_key=key, now_iso="2026-11-08T12:00:00+00:00")\n\n\nclass ReplayHardeningTests(unittest.TestCase):\n    def setUp(self):\n        self.calls = []\n        self.calls_lock = Lock()\n\n    def effect(self, **kwargs):\n        with self.calls_lock:\n            self.calls.append(kwargs)\n        return {"effect_status": "EFFECT_CONFIRMED"}\n\n    def adapter(self, effect=None):\n        return MODULE.GovernedEffectorAdapter(\n            adapter_id="A1", adapter_version="1", adapter_hash="AH1",\n            effector_id="E1", effector_callable=effect or self.effect,\n            allowed_effect_classes=["TEST"])\n\n    def test_changed_key_cannot_replay(self):\n        a = self.adapter()\n        self.assertEqual(a.execute(**inputs())["status"], "EFFECT_CONFIRMED")\n        self.assertEqual(a.execute(**inputs(key="K2"))["reason"], "effect_attempt_replay")\n        self.assertEqual(len(self.calls), 1)\n\n    def test_same_key_cannot_replay(self):\n        a = self.adapter()\n        a.execute(**inputs())\n        self.assertEqual(a.execute(**inputs())["reason"], "effect_attempt_replay")\n        self.assertEqual(len(self.calls), 1)\n\n    def test_same_lease_cannot_be_rebound_to_new_reservation(self):\n        a = self.adapter()\n        a.execute(**inputs())\n        self.assertEqual(a.execute(**inputs(reservation="R2", key="K2"))["reason"],\n                         "effect_attempt_replay")\n        self.assertEqual(len(self.calls), 1)\n\n    def test_same_reservation_cannot_be_rebound_to_new_lease(self):\n        a = self.adapter()\n        a.execute(**inputs())\n        self.assertEqual(a.execute(**inputs(lease="L2", key="K2"))["reason"],\n                         "effect_attempt_replay")\n        self.assertEqual(len(self.calls), 1)\n\n    def test_distinct_rights_can_use_same_correlation_key(self):\n        a = self.adapter()\n        self.assertEqual(a.execute(**inputs())["status"], "EFFECT_CONFIRMED")\n        other = inputs(lease="L2", reservation="R2", claim_hash="CH2")\n        self.assertEqual(a.execute(**other)["status"], "EFFECT_CONFIRMED")\n        self.assertEqual(len(self.calls), 2)\n\n    def test_concurrent_distinct_keys_allow_one_effect(self):\n        a = self.adapter()\n        barrier = Barrier(16)\n        def worker(i):\n            barrier.wait(timeout=10)\n            return a.execute(**inputs(key="K" + str(i)))["status"]\n        with ThreadPoolExecutor(max_workers=16) as pool:\n            results = list(pool.map(worker, range(16)))\n        self.assertEqual(results.count("EFFECT_CONFIRMED"), 1)\n        self.assertEqual(results.count("EXECUTION_BLOCKED_AT_FINAL_RECHECK"), 15)\n        self.assertEqual(len(self.calls), 1)\n\n    def test_unknown_outcomes_never_release_rights(self):\n        for failure in (TimeoutError, RuntimeError, None):\n            with self.subTest(failure=failure):\n                calls = []\n                def effect(**kw):\n                    calls.append(kw)\n                    if failure:\n                        raise failure("synthetic failure after possible effect")\n                    return {"unexpected": True}\n                a = self.adapter(effect)\n                first = a.execute(**inputs())\n                self.assertEqual(first["status"], "EFFECT_STATE_INDETERMINATE")\n                self.assertIs(first["blind_retry_allowed"], False)\n                self.assertEqual(a.execute(**inputs(key="K2"))["reason"], "effect_attempt_replay")\n                self.assertEqual(len(calls), 1)\n\n    def test_partial_effect_never_releases_rights(self):\n        a = self.adapter(lambda **kw: {"effect_status": "EFFECT_PARTIAL"})\n        self.assertEqual(a.execute(**inputs())["status"], "EFFECT_PARTIAL")\n        self.assertEqual(a.execute(**inputs(key="K2"))["reason"], "effect_attempt_replay")\n\n    def test_chain_identity_substitutions_block_before_effect(self):\n        for obj, field in (("handle", "lease_id"), ("handle", "reservation_id"),\n                           ("brokered_use", "lease_id"),\n                           ("brokered_use", "reservation_id"),\n                           ("brokered_use", "claim_hash")):\n            with self.subTest(obj=obj, field=field):\n                kw = inputs()\n                setattr(kw[obj], field, "OTHER")\n                self.assertEqual(self.adapter().execute(**kw)["status"],\n                                 "EXECUTION_BLOCKED_AT_FINAL_RECHECK")\n        self.assertEqual(self.calls, [])\n\n    def test_invalid_identity_is_blocked(self):\n        for field in ("lease", "reservation", "claim_hash", "key"):\n            for value in (None, "", " ", 1, True, []):\n                with self.subTest(field=field, value=value):\n                    self.assertEqual(self.adapter().execute(**inputs(**{field: value}))["status"],\n                                     "EXECUTION_BLOCKED_AT_FINAL_RECHECK")\n        self.assertEqual(self.calls, [])\n\n    def test_revocation_before_attempt_blocks_without_consuming_local_guard(self):\n        a = self.adapter()\n        kw = inputs()\n        kw["final_state"]["revoked"] = True\n        self.assertEqual(a.execute(**kw)["reason"], "last_second_revocation")\n        self.assertEqual(self.calls, [])\n        # A fresh verified input is needed; the first call never reached dispatch.\n        self.assertEqual(a.execute(**inputs())["status"], "EFFECT_CONFIRMED")\n\n    def test_reentrant_effector_cannot_dispatch_again(self):\n        nested = []\n        def effect(**kw):\n            self.calls.append(kw)\n            nested.append(a.execute(**inputs(key="nested")))\n            return {"effect_status": "EFFECT_CONFIRMED"}\n        a = self.adapter(effect)\n        self.assertEqual(a.execute(**inputs())["status"], "EFFECT_CONFIRMED")\n        self.assertEqual(nested[0]["reason"], "effect_attempt_replay")\n        self.assertEqual(len(self.calls), 1)\n\n\nif __name__ == "__main__":\n    unittest.main()\n', 'p162_g5_replay_final_lock.py': '"""Bounded G5 replay check. This never seals the global P162 Final Lock."""\nfrom pathlib import Path\nimport importlib.util\nimport sys\nimport unittest\n\n\nclass ReplayPublicInvariantCheck:\n    def step(self, *, inputs, persist=False):\n        if persist is not False or inputs != {"context": "synthetic-in-memory"}:\n            raise ValueError("synthetic non-persistent context required")\n        root = Path(__file__).resolve().parent\n        path = root / "tests/test_p162_g5_replay_hardening.py"\n        spec = importlib.util.spec_from_file_location("p162_g5_replay_tests", path)\n        module = importlib.util.module_from_spec(spec)\n        sys.modules[spec.name] = module\n        spec.loader.exec_module(module)\n        suite = unittest.defaultTestLoader.loadTestsFromModule(module)\n        result = unittest.TextTestRunner(verbosity=1).run(suite)\n        return {"status": "PASS" if result.wasSuccessful() else "FAIL",\n                "tests_run": result.testsRun, "scope": "G5 single-adapter in-process replay",\n                "p162_final_lock_executed": False, "authorization_created": False,\n                "functional_conclusion_only": True, "phenomenology_undetermined": True}\n\n\nif __name__ == "__main__":\n    result = ReplayPublicInvariantCheck().step(\n        inputs={"context": "synthetic-in-memory"}, persist=False)\n    print("P162_G5_REPLAY_" + result["status"])\n    print("P162_GLOBAL_FINAL_LOCK_NOT_EXECUTED")\n    raise SystemExit(0 if result["status"] == "PASS" else 1)\n', 'governed_effector_adapter_fast_acceptance_suite.py': '"""Compile the bounded refinement and run its synthetic public invariants."""\nfrom pathlib import Path\nimport py_compile\nimport tempfile\nfrom p162_g5_replay_final_lock import ReplayPublicInvariantCheck\n\n\ndef main():\n    root = Path(__file__).resolve().parent\n    # Keep bytecode outside the project; macOS uses /private/tmp.\n    parent = "/private/tmp" if Path("/private/tmp").is_dir() else None\n    with tempfile.TemporaryDirectory(prefix="p162-g5-compile-", dir=parent) as directory:\n        for index, relative in enumerate(("ontology/governed_effector_adapter.py",\n                                          "tests/test_p162_g5_replay_hardening.py",\n                                          "p162_g5_replay_final_lock.py")):\n            py_compile.compile(str(root / relative),\n                               cfile=str(Path(directory) / (str(index) + ".pyc")),\n                               doraise=True)\n    result = ReplayPublicInvariantCheck().step(\n        inputs={"context": "synthetic-in-memory"}, persist=False)\n    print("P162_G5_FAST_ACCEPTANCE_" + result["status"])\n    return 0 if result["status"] == "PASS" else 1\n\n\nif __name__ == "__main__":\n    raise SystemExit(main())\n'}


def digest(data):
    return hashlib.sha256(data).hexdigest()


def install(root, check=False):
    root = root.expanduser().resolve(strict=True)
    inventory = root / "ontology_inventory.txt"
    if inventory.is_symlink() or not inventory.is_file():
        raise RuntimeError("ontology_inventory.txt required; no files changed")
    if "governed_effector_adapter" not in inventory.read_text(encoding="utf-8"):
        raise RuntimeError("existing module absent from inventory; no files changed")
    target = root / "ontology/governed_effector_adapter.py"
    if target.is_symlink() or not target.is_file():
        raise RuntimeError("existing adapter required; no files changed")
    current = digest(target.read_bytes())
    expected = digest(OUTPUTS["ontology/governed_effector_adapter.py"].encode("utf-8"))
    if current not in (BASE_SHA256, expected):
        raise RuntimeError("adapter source has changed; no files changed; SHA256=" + current)
    changes = []
    for relative, text in OUTPUTS.items():
        path = root / relative
        if path.is_symlink() or not path.resolve().is_relative_to(root):
            raise RuntimeError("unsafe target: " + relative)
        if path.exists() and not path.is_file():
            raise RuntimeError("non-file target: " + relative)
        data = text.encode("utf-8")
        compile(text, relative, "exec")
        old = path.read_bytes() if path.exists() else None
        if old == data:
            continue
        # Test/lock drift is also guarded; never overwrite unrelated local work.
        if relative != "ontology/governed_effector_adapter.py" and old is not None:
            raise RuntimeError("different existing test/lock: " + relative)
        changes.append((path, old, data))
    print("SOURCE_PRECONDITION_PASS; files_to_change=" + str(len(changes)))
    if check:
        return
    # Prepare and verify every backup before the first replacement.
    for path, old, data in changes:
        if old is None:
            continue
        backup = path.with_name(path.name + "." + digest(old)[:16] + ".py.bak")
        if backup.is_symlink():
            raise RuntimeError("unsafe backup: " + str(backup))
        try:
            with backup.open("xb") as stream:
                stream.write(old)
                stream.flush()
                os.fsync(stream.fileno())
        except FileExistsError:
            if backup.read_bytes() != old:
                raise RuntimeError("backup mismatch: " + str(backup))
        print("BACKUP " + str(backup))
    completed = []
    try:
        for path, old, data in changes:
            # Recheck immediately before replacement to detect intervening edits.
            if path.is_symlink() or (path.read_bytes() if path.exists() else None) != old:
                raise RuntimeError("target changed during installation: " + str(path))
            path.parent.mkdir(parents=True, exist_ok=True)
            atomic_write(path, data)
            completed.append((path, old, data))
        print("P162_G5_REPLAY_REFINEMENT_INSTALLED")
        print("Run: python3 final_lock.py p162_g5_replay")
        print("P162_GLOBAL_FINAL_LOCK_NOT_EXECUTED")
    except BaseException:
        for path, old, data in reversed(completed):
            # Do not erase an intervening edit during rollback.
            if path.is_symlink() or not path.is_file() or path.read_bytes() != data:
                print("ROLLBACK_REQUIRES_REVIEW " + str(path))
                continue
            if old is None:
                path.unlink()
            else:
                atomic_write(path, old)
        raise


def atomic_write(path, data):
    mode = path.stat().st_mode & 0o777 if path.exists() else 0o644
    fd, temp = tempfile.mkstemp(prefix=".p162-g5-", dir=str(path.parent))
    try:
        with os.fdopen(fd, "wb") as stream:
            stream.write(data)
            stream.flush()
            os.fsync(stream.fileno())
        os.chmod(temp, mode)
        os.replace(temp, path)
    finally:
        if os.path.exists(temp):
            os.unlink(temp)


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--root", type=Path, default=ROOT)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    try:
        install(args.root, check=args.check)
    except (OSError, RuntimeError, ValueError) as exc:
        parser.exit(1, "BLOCKED: " + str(exc) + "\n")
